"""EDA outputs, all generated by code: figures, Tableau-ready tables, EDA_REPORT.md.

Input grain: one PSG Ligue 1 match (`processed/psg_l1_analytical.csv`) and one PSG official
match (`processed/psg_matches_all.csv`). Outputs in `reports/eda/`: 7 PNG figures, tidy CSV
tables (see `analysis.py` for their grain), `decision.json` and `EDA_REPORT.md` (numbers
only; interpretation is written and validated by the author in docs/FINDINGS.md).
"""

import json
import logging
from pathlib import Path
from typing import Any, Literal

import matplotlib as mpl
import numpy as np
import pandas as pd
from matplotlib.axes import Axes
from matplotlib.figure import Figure
from matplotlib.lines import Line2D
from matplotlib.typing import RcKeyType

from psg_fatigue import analysis, config
from psg_fatigue.features import HIGH_LOAD_LABEL, NORMAL_LOAD_LABEL

logger = logging.getLogger(__name__)

# Chart chrome and colours (dataviz reference palette, light surface). Categorical slots
# 1-3 only: they pass the colour-blindness checks for every pair (validated script).
SURFACE, INK, INK_SECONDARY, INK_MUTED = "#fcfcfb", "#0b0b0b", "#52514e", "#898781"
GRID, BASELINE = "#e1e0d9", "#c3c2b7"
BLUE, ORANGE, AQUA, RED = "#2a78d6", "#eb6834", "#1baf7a", "#e34948"
# Colour follows the bucket in every figure: orange = high load, blue = normal load.
BUCKET_COLORS = {"High": ORANGE, "Normal": BLUE}
COMPETITION_ORDER = [
    "Ligue 1",
    "UEFA Champions League",
    "Coupe de France",
    "Trophée des Champions",
    "UEFA Super Cup",
    "FIFA Club World Cup",
    "FIFA Intercontinental Cup",
]
STYLE: dict[RcKeyType, Any] = {  # keys checked by mypy against matplotlib's rc names
    "font.family": "DejaVu Sans",  # bundled with matplotlib: identical PNGs on every machine
    "font.size": 9,
    "text.color": INK,
    "axes.titlesize": 10,
    "axes.titleweight": "bold",
    "axes.titlelocation": "left",
    "axes.labelcolor": INK_SECONDARY,
    "axes.edgecolor": BASELINE,
    "axes.facecolor": SURFACE,
    "axes.spines.top": False,
    "axes.spines.right": False,
    "xtick.color": INK_MUTED,
    "ytick.color": INK_MUTED,
    "xtick.labelcolor": INK_SECONDARY,
    "ytick.labelcolor": INK_SECONDARY,
    "figure.facecolor": SURFACE,
    "savefig.facecolor": SURFACE,
    "legend.frameon": False,
    "lines.linewidth": 2,
    "lines.solid_capstyle": "round",
}
DPI = 150


# --- Helpers ----------------------------------------------------------------------


def bucket_color(bucket: str) -> str:
    """Orange for any high-load bucket label, blue for normal load."""
    return BUCKET_COLORS["High" if bucket.startswith("High") else "Normal"]


def style_axis(ax: Axes, grid: Literal["both", "x", "y"] = "y") -> None:
    """Recessive hairline grid behind the data."""
    ax.set_axisbelow(True)
    ax.grid(axis=grid, color=GRID, linewidth=0.8, linestyle="-")
    ax.tick_params(length=0)


def save(fig: Figure, path: Path) -> None:
    """Write a PNG without a version stamp in its metadata (byte-identical reruns)."""
    fig.savefig(path, dpi=DPI, metadata={"Software": None}, bbox_inches="tight")
    logger.info("Wrote %s", path.as_posix())


def fmt(value: Any, digits: int = 3) -> str:
    """Number formatting for the Markdown report."""
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return ""
    if isinstance(value, (bool, np.bool_)):
        return "yes" if value else "no"
    if isinstance(value, (int, np.integer)):
        return str(int(value))
    return f"{float(value):.{digits}f}"


def markdown_table(table: pd.DataFrame, digits: int = 3) -> str:
    """Small DataFrame -> Markdown table with formatted numbers."""
    header = "| " + " | ".join(str(column) for column in table.columns) + " |"
    separator = "|" + "---|" * len(table.columns)
    body = [
        "| " + " | ".join(fmt(v, digits) if not isinstance(v, str) else v for v in row) + " |"
        for row in table.itertuples(index=False)
    ]
    return "\n".join([header, separator, *body])


def write_table(table: pd.DataFrame, path: Path) -> None:
    """Tidy CSV for Tableau: ISO dates, 6 decimals, Unix line endings."""
    decimals = dict.fromkeys(table.select_dtypes("float").columns, 6)  # dates untouched
    table.round(decimals).to_csv(path, index=False, lineterminator="\n", date_format="%Y-%m-%d")
    logger.info("Wrote %s (%d rows)", path.as_posix(), len(table))


# --- Figures ----------------------------------------------------------------------


def figure_calendar(matches: pd.DataFrame, path: Path) -> None:
    """Fig. 1: every official match by date, one row per competition."""
    fig = Figure(figsize=(9, 3.6))
    ax = fig.subplots()
    group_color = {"Ligue 1": BLUE, "UEFA Champions League": ORANGE}
    rows = [c for c in COMPETITION_ORDER if c in set(matches["competition"])]
    for position, competition in enumerate(reversed(rows)):
        subset = matches[matches["competition"] == competition]
        ax.scatter(
            subset["match_date"],
            np.full(len(subset), position),
            s=30,
            color=group_color.get(competition, AQUA),
            edgecolors=SURFACE,
            linewidths=0.8,
            zorder=3,
        )
    ax.set_yticks(
        range(len(rows)), [f"{c} ({(matches['competition'] == c).sum()})" for c in reversed(rows)]
    )
    for season, group in matches.groupby("season"):
        start = group["match_date"].min()
        ax.axvline(start, color=GRID, linewidth=0.8, zorder=1)
        ax.text(start, len(rows) - 0.4, f" {season}", color=INK_SECONDARY, va="bottom", fontsize=8)
    style_axis(ax, grid="x")
    ax.grid(False)
    ax.set_ylim(-0.6, len(rows) - 0.1)
    ax.set_xlabel("Match date")
    ax.set_title(
        f"Official PSG matches under Luis Enrique by competition (n = {len(matches)}; "
        "count per competition in brackets)",
        pad=18,
    )
    legend = [
        Line2D([], [], marker="o", linestyle="", color=BLUE, label="Ligue 1 (analysis rows)"),
        Line2D([], [], marker="o", linestyle="", color=ORANGE, label="Champions League"),
        Line2D([], [], marker="o", linestyle="", color=AQUA, label="Other official competitions"),
    ]
    ax.legend(handles=legend, loc="upper left", bbox_to_anchor=(0, -0.18), ncols=3)
    save(fig, path)


def figure_rest_days(l1: pd.DataFrame, path: Path) -> None:
    """Fig. 2: distribution of rest days before Ligue 1 matches, thresholds 3 and 4."""
    max_shown = 21
    counts = l1["rest_days"].value_counts().sort_index()
    shown = counts[counts.index <= max_shown]
    hidden = l1.loc[l1["rest_days"] > max_shown, "rest_days"].sort_values().tolist()
    fig = Figure(figsize=(8, 3.6))
    ax = fig.subplots()
    colors = [ORANGE if d <= config.HIGH_LOAD_MAX_REST_DAYS else BLUE for d in shown.index]
    ax.bar(shown.index, shown.to_numpy(), width=0.7, color=colors, zorder=3)
    top = shown.max()
    for threshold, label, height in [
        (config.HIGH_LOAD_MAX_REST_DAYS, "primary threshold: ≤3 days", 1.22),
        (config.ALT_HIGH_LOAD_MAX_REST_DAYS, "sensitivity: ≤4 days", 1.10),
    ]:
        ax.plot([threshold + 0.5] * 2, [0, top * height], color=INK_MUTED, linewidth=1, zorder=2)
        ax.text(threshold + 0.6, top * height, label, color=INK_SECONDARY, fontsize=8, va="center")
    for day in (3, 4):
        if day in shown.index:
            ax.text(day, shown[day] + 0.4, str(shown[day]), ha="center", color=INK, fontsize=8)
    style_axis(ax)
    ax.set_xticks(range(0, max_shown + 1, 3))
    ax.set_xlim(0, max_shown + 1)
    ax.set_ylim(0, top * 1.3)
    ax.set_xlabel("Rest days before the match (calendar days since previous official match)")
    ax.set_ylabel("Ligue 1 matches")
    ax.set_title(f"Rest before PSG's Ligue 1 matches (n = {len(l1)})")
    if hidden:
        values = ", ".join(str(int(v)) for v in hidden)
        ax.text(
            1.0,
            -0.22,
            f"Not shown: {len(hidden)} season opener(s) at {values} days",
            transform=ax.transAxes,
            ha="right",
            color=INK_MUTED,
            fontsize=8,
        )
    ax.legend(
        handles=[
            Line2D([], [], marker="s", linestyle="", color=ORANGE, label=HIGH_LOAD_LABEL),
            Line2D([], [], marker="s", linestyle="", color=BLUE, label=NORMAL_LOAD_LABEL),
        ],
        loc="upper right",
    )
    save(fig, path)


def figure_performance(summary: pd.DataFrame, path: Path) -> None:
    """Fig. 3: win rate, points per match and shots-on-target difference by bucket."""
    panels = [
        ("win_rate", "Win rate (%)", 100.0),
        ("points_per_match", "Points per match", 1.0),
        ("sot_diff", "Shots-on-target difference", 1.0),
    ]
    primary = summary[summary["definition"] == "primary"]
    fig = Figure(figsize=(9, 3.4))
    axes = fig.subplots(1, 3)
    for ax, (kpi, label, scale) in zip(axes, panels, strict=True):
        rows = primary[primary["kpi"] == kpi].reset_index(drop=True)
        x = np.arange(len(rows))
        means, lows, highs = (rows[c].to_numpy() * scale for c in ("mean", "ci_low", "ci_high"))
        ax.bar(x, means, width=0.45, color=[bucket_color(b) for b in rows["bucket"]], zorder=3)
        ax.errorbar(
            x,
            means,
            yerr=[means - lows, highs - means],
            fmt="none",
            ecolor=INK_SECONDARY,
            elinewidth=1,
            capsize=3,
            zorder=4,
        )
        for xi, mean, high in zip(x, means, highs, strict=True):
            ax.annotate(
                f"{mean:.2f}" if scale == 1 else f"{mean:.1f}",
                (xi, high),
                xytext=(0, 4),
                textcoords="offset points",
                ha="center",
                va="bottom",
                color=INK,
                fontsize=8,
            )
        ax.set_xticks(
            x,
            [f"{b.split(' ')[0]}\nn = {n}" for b, n in zip(rows["bucket"], rows["n"], strict=True)],
        )
        ax.axhline(0, color=BASELINE, linewidth=1)
        ax.set_ylim(min(0.0, float(lows.min())), float(highs.max()) * 1.2)  # room for labels
        style_axis(ax)
        ax.set_title(label, fontsize=9)
    fig.suptitle(
        "PSG Ligue 1 performance by rest before the match "
        "(bars: mean; whiskers: 90% bootstrap CI; High = ≤3 rest days)",
        x=0.01,
        ha="left",
        fontweight="bold",
        fontsize=10,
    )
    fig.tight_layout()
    save(fig, path)


def kpi_value(summary: pd.DataFrame, bucket: str, kpi: str, column: str = "mean") -> float:
    """One value of the primary-definition summary table (bucket x KPI)."""
    rows = summary[
        (summary["definition"] == "primary")
        & (summary["bucket"] == bucket)
        & (summary["kpi"] == kpi)
    ]
    return float(rows[column].to_numpy(dtype=float)[0])


def figure_implied_vs_actual(summary: pd.DataFrame, path: Path) -> None:
    """Fig. 4: dumbbell of mean implied win probability vs actual win rate, by bucket."""
    buckets = [NORMAL_LOAD_LABEL, HIGH_LOAD_LABEL]
    fig = Figure(figsize=(8, 2.6))
    ax = fig.subplots()
    for y, bucket in enumerate(buckets):
        implied = kpi_value(summary, bucket, "implied_win_prob")
        actual = kpi_value(summary, bucket, "win_rate")
        color = bucket_color(bucket)
        ax.plot([implied, actual], [y, y], color=GRID, linewidth=3, zorder=2)
        ax.scatter(implied, y, s=70, facecolors=SURFACE, edgecolors=color, linewidths=2, zorder=3)
        ax.scatter(actual, y, s=70, color=color, edgecolors=SURFACE, linewidths=1.5, zorder=4)
        for value, offset in ((implied, -0.32), (actual, 0.22)):
            ax.text(value, y + offset, f"{value:.3f}", ha="center", color=INK, fontsize=8)
    labels = [f"{b}\nn = {kpi_value(summary, b, 'win_rate', 'n'):.0f}" for b in buckets]
    ax.set_yticks(range(len(buckets)), labels)
    ax.set_ylim(-0.7, len(buckets) - 0.3)
    ax.set_xlim(0.5, 0.9)
    style_axis(ax, grid="x")
    ax.set_xlabel("Probability of a PSG win (0-1)")
    ax.set_title("Did the market see it coming? Mean implied win probability vs actual win rate")
    ax.legend(
        handles=[
            Line2D(
                [],
                [],
                marker="o",
                linestyle="",
                markerfacecolor=SURFACE,
                markeredgecolor=INK_SECONDARY,
                label="Implied by closing odds (mean)",
            ),
            Line2D([], [], marker="o", linestyle="", color=INK_SECONDARY, label="Actual win rate"),
        ],
        loc="upper left",
        bbox_to_anchor=(0, -0.3),
        ncols=2,
    )
    save(fig, path)


def figure_residuals(sensitivity: pd.DataFrame, path: Path) -> None:
    """Fig. 5: mean residual with 90% CI by bucket, for the primary and sensitivity definitions."""
    rows = []
    for record in sensitivity.itertuples():
        rows.append(
            (
                f"{record.definition}: high  (n = {record.n_high})",
                "High",
                record.high_mean_residual,
                record.high_ci_low,
                record.high_ci_high,
            )
        )
        rows.append(
            (
                f"{record.definition}: normal  (n = {record.n_normal})",
                "Normal",
                record.normal_mean_residual,
                record.normal_ci_low,
                record.normal_ci_high,
            )
        )
    fig = Figure(figsize=(8, 4))
    ax = fig.subplots()
    for y, (_, bucket, mean, low, high) in enumerate(reversed(rows)):
        color = BUCKET_COLORS[bucket]
        ax.plot([low, high], [y, y], color=color, linewidth=2, zorder=3)
        ax.scatter(mean, y, s=50, color=color, edgecolors=SURFACE, linewidths=1.5, zorder=4)
        ax.text(high + 0.01, y, f"{mean:+.3f}", va="center", color=INK, fontsize=8)
    ax.axvline(0, color=INK_MUTED, linewidth=1, zorder=2)
    ax.set_yticks(range(len(rows)), [label for label, *_ in reversed(rows)])
    style_axis(ax, grid="x")
    ax.set_xlabel("Mean residual = actual win (0/1) - implied win probability")
    ax.set_title("Mean residual by load bucket, with 90% bootstrap CI")
    ax.text(
        0,
        -0.2,
        "Decision rule: adjust only if the high-load mean is negative and its CI lies "
        "entirely left of 0. Definitions: primary <=3 rest days; alt4 <=4; 14d >=4 matches "
        "in 14 days; b365c primary with Bet365 closing odds.",
        transform=ax.transAxes,
        color=INK_MUTED,
        fontsize=7,
        wrap=True,
    )
    save(fig, path)


def figure_season_start(window: pd.DataFrame, path: Path) -> None:
    """Fig. 6: cumulative residual over the first 8 league matches, one line per season."""
    fig = Figure(figsize=(8, 3.8))
    ax = fig.subplots()
    handles = []
    grey_markers = iter(["s", "^", "D", "v"])
    for season, group in window.groupby("season", sort=True):
        highlight = season == config.POST_CWC_SEASON
        color = RED if highlight else BASELINE
        label = f"{season} ({int(group['summer_break_days'].iloc[0])}-day summer break)"
        (line,) = ax.plot(
            group["match_index"],
            group["cum_residual"],
            color=color,
            linewidth=2.5 if highlight else 2,
            marker="o" if highlight else next(grey_markers),
            markersize=6,
            markeredgecolor=SURFACE,
            zorder=4 if highlight else 3,
            label=label,
        )
        handles.append(line)
        if highlight:
            ax.text(
                float(group["match_index"].iloc[-1]) + 0.12,
                float(group["cum_residual"].iloc[-1]),
                str(season),
                va="center",
                color=INK,
                fontsize=8,
                fontweight="bold",
            )
    ax.axhline(0, color=INK_MUTED, linewidth=1, zorder=2)
    style_axis(ax)
    ax.set_xticks(range(1, config.SEASON_START_WINDOW_MATCHES + 1))
    ax.set_xlim(0.7, config.SEASON_START_WINDOW_MATCHES + 0.8)
    ax.set_xlabel("PSG Ligue 1 match of the season (by date)")
    ax.set_ylabel("Cumulative residual (wins above implied)")
    ax.set_title("Cumulative surprise over the first 8 Ligue 1 matches of each season")
    ax.legend(handles=handles, loc="upper left", bbox_to_anchor=(0, -0.18), ncols=2)
    save(fig, path)


def figure_calibration(calibration: pd.DataFrame, path: Path) -> None:
    """Fig. 7: actual win rate vs mean implied probability, in probability bins."""
    fig = Figure(figsize=(5, 4.6))
    ax = fig.subplots()
    ax.plot([0.2, 1.0], [0.2, 1.0], color=BASELINE, linewidth=1, zorder=2)
    ax.text(
        0.24,
        0.26,
        "perfect calibration",
        color=INK_MUTED,
        fontsize=7,
        rotation=45,
        rotation_mode="anchor",
        transform_rotates_text=True,
    )
    x = calibration["mean_implied_win_prob"].to_numpy()
    y = calibration["actual_win_rate"].to_numpy()
    ax.errorbar(
        x,
        y,
        yerr=[y - calibration["ci_low"], calibration["ci_high"] - y],
        fmt="none",
        ecolor=BLUE,
        elinewidth=1.5,
        capsize=3,
        zorder=3,
    )
    ax.scatter(x, y, s=45, color=BLUE, edgecolors=SURFACE, linewidths=1.5, zorder=4)
    for xi, yi, n in zip(x, y, calibration["n"], strict=True):
        ax.text(xi + 0.015, yi, f"n = {n}", va="center", color=INK_SECONDARY, fontsize=7)
    style_axis(ax, grid="both")
    ax.set_xlim(0.2, 1.0)
    ax.set_ylim(0.0, 1.05)
    ax.set_xlabel("Mean implied win probability in the bin (0-1)")
    ax.set_ylabel("Actual PSG win rate (0-1)")
    ax.set_title("Calibration of closing odds\n(whiskers: 90% bootstrap CI)")
    save(fig, path)


# --- Report -----------------------------------------------------------------------


def build_report(
    l1: pd.DataFrame,
    matches: pd.DataFrame,
    summary: pd.DataFrame,
    sensitivity: pd.DataFrame,
    decision: dict[str, Any],
    window_summary: pd.DataFrame,
    calibration: pd.DataFrame,
) -> str:
    """EDA_REPORT.md: one section per figure with the numbers behind it (no interpretation)."""
    primary = summary[summary["definition"] == "primary"]
    kpi_table = primary.pivot(index="bucket", columns="kpi", values="mean").reset_index()
    kpi_table = kpi_table[
        [
            "bucket",
            "win_rate",
            "points_per_match",
            "sot_diff",
            "implied_win_prob",
            "mean_residual",
            "brier",
            "roi_flat",
        ]
    ]
    n_by_bucket = primary[primary["kpi"] == "win_rate"].set_index("bucket")["n"]
    kpi_table.insert(1, "n", kpi_table["bucket"].map(n_by_bucket))
    ci_table = primary[["bucket", "kpi", "n", "mean", "ci_low", "ci_high"]]
    by_competition = matches.groupby(["season", "competition"]).size().unstack(fill_value=0)
    by_competition = by_competition[[c for c in COMPETITION_ORDER if c in by_competition.columns]]
    by_competition = by_competition.reset_index()
    rest = l1["rest_days"]
    prev = (
        l1[l1["high_load"]]["prev_competition"].value_counts().rename_axis("previous competition")
    )
    sources = l1["odds_source"].value_counts().rename_axis("odds_source").reset_index()
    sens_table = sensitivity[
        [
            "definition",
            "n_high",
            "n_normal",
            "high_mean_residual",
            "high_ci_low",
            "high_ci_high",
            "diff_high_minus_normal",
            "diff_ci_low",
            "diff_ci_high",
            "rule_satisfied",
        ]
    ]
    lines = [
        "# EDA report",
        "",
        "Generated by `uv run psg-fatigue eda` from `data/processed/`. Numbers only: "
        "interpretation is in `docs/FINDINGS.md`. Confidence intervals are 90% percentile "
        f"bootstrap intervals ({config.BOOTSTRAP_RESAMPLES} resamples, seed {config.RANDOM_SEED}).",
        "",
        f"- Ligue 1 matches analysed: **{len(l1)}** "
        f"({l1['match_date'].min().date()} to {l1['match_date'].max().date()})",
        f"- Official matches (all competitions) used for load: **{len(matches)}**",
        "- Reference odds used (count of matches per source):",
        "",
        markdown_table(sources),
        "",
        "## Figure 1 - Calendar load (`fig1_calendar_timeline.png`)",
        "",
        "Official matches per season and competition:",
        "",
        markdown_table(by_competition),
        "",
        "## Figure 2 - Rest days before Ligue 1 matches (`fig2_rest_days_distribution.png`)",
        "",
        f"- Rest days: min {fmt(rest.min())}, median {fmt(rest.median(), 1)}, "
        f"max {fmt(rest.max())}.",
        f"- High load (<= 3 days): **{int(l1['high_load'].sum())}** matches; "
        f"<= 4 days: {int(l1['high_load_alt4'].sum())}; "
        f">= 4 matches in 14 days: {int(l1['high_load_14d'].sum())}.",
        "- Competition of the previous match, high-load matches:",
        "",
        markdown_table(prev.reset_index()),
        "",
        "## Figure 3 - Performance by load bucket (`fig3_performance_by_bucket.png`)",
        "",
        "Means by primary bucket (win rate and probabilities on a 0-1 scale):",
        "",
        markdown_table(kpi_table),
        "",
        "With 90% bootstrap CIs:",
        "",
        markdown_table(ci_table),
        "",
        "## Figure 4 - Implied vs actual win probability (`fig4_implied_vs_actual.png`)",
        "",
        "See the `implied_win_prob` and `win_rate` rows above.",
        "",
        "## Figure 5 - Mean residual by definition (`fig5_residual_by_definition.png`)",
        "",
        markdown_table(sens_table),
        "",
        "## Figure 6 - Season-start window (`fig6_season_start.png`)",
        "",
        "First 8 Ligue 1 matches of each season:",
        "",
        markdown_table(window_summary),
        "",
        "## Figure 7 - Calibration (`fig7_calibration.png`)",
        "",
        markdown_table(calibration),
        "",
        "## Decision rule (`decision.json`)",
        "",
        f"- Rule: {decision['rule']}",
        f"- High-load mean residual: **{decision['high_load_mean_residual']:+.4f}**, "
        f"90% CI [{decision['high_load_ci90'][0]:+.4f}, {decision['high_load_ci90'][1]:+.4f}] "
        f"(n = {decision['n_high_load']}).",
        f"- Normal-load mean residual: {decision['normal_load_mean_residual']:+.4f}, "
        f"90% CI [{decision['normal_load_ci90'][0]:+.4f}, {decision['normal_load_ci90'][1]:+.4f}] "
        f"(n = {decision['n_normal_load']}).",
        f"- Difference high - normal: {decision['difference_high_minus_normal']:+.4f}, "
        f"90% CI [{decision['difference_ci90'][0]:+.4f}, {decision['difference_ci90'][1]:+.4f}].",
        f"- Rule satisfied: **{fmt(decision['rule_satisfied'])}** -> {decision['conclusion']}.",
        "",
    ]
    return "\n".join(lines)


def run_eda(processed_dir: Path, out_dir: Path) -> dict[str, Any]:
    """Compute every statistic, write tables, figures and the report. Returns the decision."""
    out_dir.mkdir(parents=True, exist_ok=True)
    l1 = pd.read_csv(processed_dir / "psg_l1_analytical.csv", parse_dates=["match_date"])
    matches = pd.read_csv(processed_dir / "psg_matches_all.csv", parse_dates=["match_date"])
    logger.info("EDA input: %d Ligue 1 matches, %d official matches", len(l1), len(matches))

    summary = analysis.summary_by_bucket(l1)
    sensitivity = analysis.sensitivity(l1)
    decision = analysis.decision(l1, sensitivity)
    window = analysis.season_start(l1)
    window_summary = analysis.season_start_summary(window)
    calibration = analysis.calibration(l1)

    write_table(summary, out_dir / "summary_by_bucket.csv")
    write_table(sensitivity, out_dir / "sensitivity.csv")
    write_table(window, out_dir / "season_start.csv")
    write_table(window_summary, out_dir / "season_start_summary.csv")
    write_table(calibration, out_dir / "calibration.csv")
    (out_dir / "decision.json").write_text(json.dumps(decision, indent=2) + "\n", "utf-8")

    with mpl.rc_context():
        mpl.rcParams.update(STYLE)
        figure_calendar(matches, out_dir / "fig1_calendar_timeline.png")
        figure_rest_days(l1, out_dir / "fig2_rest_days_distribution.png")
        figure_performance(summary, out_dir / "fig3_performance_by_bucket.png")
        figure_implied_vs_actual(summary, out_dir / "fig4_implied_vs_actual.png")
        figure_residuals(sensitivity, out_dir / "fig5_residual_by_definition.png")
        figure_season_start(window, out_dir / "fig6_season_start.png")
        figure_calibration(calibration, out_dir / "fig7_calibration.png")

    report = build_report(l1, matches, summary, sensitivity, decision, window_summary, calibration)
    (out_dir / "EDA_REPORT.md").write_text(report, "utf-8")
    logger.info(
        "Decision rule satisfied: %s -> %s", decision["rule_satisfied"], decision["conclusion"]
    )
    return decision
